cd /home/judge/solution && set -a && . deploy/compose/.env && set +a && python3 - <<'PY'
import os,json,urllib.request,base64
base='http://127.0.0.1:'+os.environ['DITTO_PORT']+'/api/2/things/'
for name in ['control','smart:excavator-1','smart:truck-101','smart:stockpile','smart:plant','smart:geology','smart:tailings','smart:shift']:
 tid='org.aktogay:'+name if name=='control' else 'org.aktogay.'+name
 req=urllib.request.Request(base+tid,headers={'Authorization':'Basic '+base64.b64encode(('ditto:'+os.environ['DITTO_PASSWORD']).encode()).decode()})
 try:
  d=json.load(urllib.request.urlopen(req,timeout=8)); f={k:v.get('properties',{}) for k,v in d.get('features',{}).items()}; print(tid,json.dumps({'attributes':d.get('attributes'), 'features':f},ensure_ascii=False)[:11000])
 except Exception as e: print(str(e))
PY

