  1	/**
  2	 * Качество руды (содержание меди) и извлечение на обогатительной фабрике.
  3	 *
  4	 * Содержание Cu в забое меняется по ходу отработки блока (рудное тело неоднородно):
  5	 * базовое значение + медленная волна с периодом в несколько часов. Фабрика работает лучше всего,
  6	 * когда питание ровное и близко к целевому: отклонение снижает извлечение меди в концентрат.
  7	 */
  8	import type { SimConfig } from './config';
  9	import type { Excavator } from './types';
 10	
 11	/** Содержание меди в забое экскаватора в момент времени, %. */
 12	export function gradeAt(ex: Excavator, now: number): number {
 13	  if (ex.gradeBase <= 0) return 0;
 14	  const g = ex.gradeBase + ex.gradeAmp * Math.sin((2 * Math.PI * now) / ex.gradePeriodSec + ex.gradePhase);
 15	  return Math.max(0.05, g);
 16	}
 17	
 18	/** Извлечение меди в концентрат (доля) при заданном содержании в питании. */
 19	export function recovery(cfg: SimConfig, gradePct: number): number {
 20	  const dev = Math.abs(gradePct - cfg.grade.targetPct);
 21	  return Math.max(0.5, cfg.grade.recoveryMax - cfg.grade.recoveryPenaltyPerPct * dev);
 22	}
 23	
 24	export function inBand(cfg: SimConfig, gradePct: number): boolean {
 25	  return Math.abs(gradePct - cfg.grade.targetPct) <= cfg.grade.bandPct;
